reply:
```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment> a owl:Ontology ;
  rdfs:label "Educational Assessment Ontology" ;
  rdfs:comment "Models classification claims about educational assessment, testing, validity and reliability as stated in the source corpus. Where the corpus disagrees with itself (coordinate vs. subordinate classifications), both axioms are asserted and the tension is noted in rdfs:comment." .

############################################
# 0. CORE CLASS
############################################

ea:Assessment a owl:Class ;
  rdfs:label "Assessment" ;
  skos:altLabel "educational evaluation", "evaluation" ;
  rdfs:comment "Systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve learning. Assessment is often used interchangeably with 'test' but is not limited to tests." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:label "Test" ;
  skos:altLabel "examination", "exam" ;
  rdfs:comment "A test (examination) is an assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness or classification. Every test is an assessment, but assessment is not limited to tests." .

############################################
# 1. GRANULARITY AXIS (no named kinds, axis only)
############################################

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:GranularityLevel ;
  rdfs:comment "Assessment can focus on the individual learner, the learning community, a course, a program, the institution, or the educational system as a whole (granularity)." .

ea:GranularityLevel a owl:Class .
ea:LearnerGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:LearningCommunityGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:CourseGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:ProgramGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:InstitutionGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .
ea:EducationalSystemGranularity a owl:Class ; rdfs:subClassOf ea:GranularityLevel .

ea:GranularityLevel owl:disjointUnionOf
  ( ea:LearnerGranularity ea:LearningCommunityGranularity ea:CourseGranularity
    ea:ProgramGranularity ea:InstitutionGranularity ea:EducationalSystemGranularity ) .

############################################
# 2. PURPOSE / TIMING AXIS
############################################

ea:hasPurpose a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:PurposeCategory .

ea:PurposeCategory a owl:Class .
ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .

ea:PurposeCategory owl:disjointUnionOf
  ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:PlacementAssessment a owl:Class ;
  rdfs:label "Placement Assessment" ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] ;
  rdfs:comment "Used to place students according to prior achievement, knowledge level, or personal characteristics, conducted before instruction to establish a baseline." .

ea:FormativeAssessment a owl:Class ;
  rdfs:label "Formative Assessment" ;
  skos:altLabel "formative evaluation", "assessment for learning", "educative assessment", "classroom assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] ;
  rdfs:comment "Carried out during the course to provide feedback and modify teaching/learning; not necessarily graded." .

ea:SummativeAssessment a owl:Class ;
  rdfs:label "Summative Assessment" ;
  skos:altLabel "summative evaluation", "assessment of learning" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] ;
  rdfs:comment "Carried out at the end of a course/project to assign a grade and summarize learning." .

ea:DiagnosticAssessment a owl:Class ;
  rdfs:label "Diagnostic Assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: One passage lists Placement/Formative/Summative/Diagnostic as four coordinate (sibling, pairwise-disjoint via hasPurpose) categories. Another passage states 'A common form of formative assessment is diagnostic assessment', subordinating DiagnosticAssessment under FormativeAssessment. Both axioms are asserted." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:PlacementAssessment ea:FormativeAssessment ea:SummativeAssessment ea:DiagnosticAssessment ) .

############################################
# 2b. ASSESSOR AXIS
############################################

ea:hasAssessor a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:AssessorCategory ;
  rdfs:comment "A formative assessment might be conducted by a teacher (or peer) or by the learner." .

ea:AssessorCategory a owl:Class .
ea:TeacherAssessor a owl:Class ; rdfs:subClassOf ea:AssessorCategory .
ea:PeerAssessor a owl:Class ; rdfs:subClassOf ea:AssessorCategory .
ea:LearnerAssessor a owl:Class ; rdfs:subClassOf ea:AssessorCategory .

ea:AssessorCategory owl:disjointUnionOf ( ea:TeacherAssessor ea:PeerAssessor ea:LearnerAssessor ) .

ea:SelfAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAssessor ; owl:someValuesFrom ea:LearnerAssessor ] ) ] ;
  rdfs:subClassOf ea:DiagnosticAssessment ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

ea:PeerAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAssessor ; owl:someValuesFrom ea:PeerAssessor ] ) ] .

############################################
# 3. OBJECTIVE / SUBJECTIVE AXIS
############################################

ea:hasObjectivity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ObjectivityCategory .

ea:ObjectivityCategory a owl:Class .
ea:ObjectiveCategory a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:SubjectiveCategory a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:ObjectivityCategory owl:disjointUnionOf ( ea:ObjectiveCategory ea:SubjectiveCategory ) .

ea:ObjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:ObjectiveCategory ] ) ] ;
  rdfs:comment "A form of questioning that has a single correct answer." .

ea:SubjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:SubjectiveCategory ] ) ] ;
  rdfs:comment "A form of questioning that may have more than one correct answer." .

############################################
# 4. REFERENCING AXIS
############################################

ea:hasReferencing a owl:ObjectProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:ReferencingCategory ;
  rdfs:comment "Each referencing method can be used to grade the same test paper, so hasReferencing is not declared functional." .

ea:ReferencingCategory a owl:Class .
ea:CriterionReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:NormReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:IpsativeReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:ReferencingCategory owl:disjointUnionOf ( ea:CriterionReferencing ea:NormReferencing ea:IpsativeReferencing ) .

ea:CriterionReferencedAssessment a owl:Class ;
  skos:altLabel "standards-based assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] ;
  rdfs:comment "Candidates are measured against defined, objective criteria. Also called standards-based assessment." .

ea:NormReferencedAssessment a owl:Class ;
  skos:altLabel "normative assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] ;
  rdfs:comment "Relative to the student body taking the test; compares students to each other ('grading on the curve')." .

ea:IpsativeAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:IpsativeReferencing ] ) ] ;
  rdfs:comment "Self-comparison either in the same domain over time or across domains within the same student." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:CriterionReferencedAssessment ea:NormReferencedAssessment ea:IpsativeAssessment ) .

ea:StandardsBasedAssessment a owl:Class ;
  owl:equivalentClass ea:CriterionReferencedAssessment ;
  rdfs:comment "Criterion-referenced tests have also been called standards-based assessments." .

############################################
# 5. FORMAL / INFORMAL AXIS
############################################

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:FormalityCategory .

ea:FormalityCategory a owl:Class .
ea:FormalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:FormalityCategory owl:disjointUnionOf ( ea:FormalCategory ea:InformalCategory ) .

ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalCategory ] ) ] ;
  rdfs:comment "Usually implies a written document given a numerical score or grade." .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalCategory ] ) ] ;
  rdfs:comment "Occurs more casually and does not contribute to a student's final grade." .

############################################
# 6. INTERNAL / EXTERNAL AXIS
############################################

ea:hasAdministrationScope a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:AdministrationScopeCategory .

ea:AdministrationScopeCategory a owl:Class .
ea:InternalScope a owl:Class ; rdfs:subClassOf ea:AdministrationScopeCategory .
ea:ExternalScope a owl:Class ; rdfs:subClassOf ea:AdministrationScopeCategory .
ea:AdministrationScopeCategory owl:disjointUnionOf ( ea:InternalScope ea:ExternalScope ) .

ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationScope ; owl:someValuesFrom ea:InternalScope ] ) ] ;
  rdfs:comment "Set and marked by the school (teachers)." .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationScope ; owl:someValuesFrom ea:ExternalScope ] ) ] ;
  rdfs:comment "Set by the governing body and marked by unbiased personnel." .

############################################
# 7. STANDARDIZATION AXIS (Test only)
############################################

ea:hasStandardization a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:StandardizationCategory .

ea:StandardizationCategory a owl:Class .
ea:StandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:StandardizationCategory owl:disjointUnionOf ( ea:StandardizedCategory ea:NonStandardizedCategory ) .

ea:StandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedCategory ] ) ] ;
  rdfs:comment "Administered and scored in a consistent, standard manner for all test takers." .

ea:NonStandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedCategory ] ) ] ;
  rdfs:comment "Significantly different tests are given to different test takers, or conditions/scoring differ." .

############################################
# 8. STAKES AXIS
############################################

ea:hasStakesLevel a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ;
  rdfs:range ea:StakesCategory .

ea:StakesCategory a owl:Class .
ea:HighStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:StakesCategory owl:disjointUnionOf ( ea:HighStakesCategory ea:LowStakesCategory ) .

ea:HighStakesAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  rdfs:comment "A test with a desired reward for good performance / important consequences for the test taker." .

ea:LowStakesAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:LowStakesCategory ] ) ] .

ea:HighStakesTest a owl:Class ; owl:equivalentClass [ owl:intersectionOf ( ea:Test ea:HighStakesAssessment ) ] .
ea:LowStakesTest a owl:Class ; owl:equivalentClass [ owl:intersectionOf ( ea:Test ea:LowStakesAssessment ) ] .

############################################
# 9. REFERENCING AXIS APPLIED TO TEST
############################################

ea:NormReferencedTest a owl:Class ;
  skos:altLabel "NRT" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test ea:NormReferencedAssessment ) ] ;
  rdfs:comment "Robert Glaser coined the terms norm-referenced test and criterion-referenced test." .

ea:CriterionReferencedTest a owl:Class ;
  skos:altLabel "CRT" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test ea:CriterionReferencedAssessment ) ] .

############################################
# 10. OTHER NAMED ASSESSMENT KINDS
############################################

ea:hasComponent a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Assessment .

ea:PerformanceBasedAssessment a owl:Class ;
  skos:altLabel "performance assessment" ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Similar to summative assessment, focuses on achievement; a well-defined task requires an extended response, often in real-world application settings." .

ea:ProductBasedPerformanceAssessment a owl:Class ; rdfs:subClassOf ea:PerformanceBasedAssessment ;
  rdfs:comment "The performance results in a product, e.g. painting, portfolio, paper, or exhibition." .
ea:LivePerformanceAssessment a owl:Class ; rdfs:subClassOf ea:PerformanceBasedAssessment ;
  rdfs:comment "The performance consists of a performance event, e.g. speech, athletic skill, musical recital, reading." .
[] a owl:AllDisjointClasses ; owl:members ( ea:ProductBasedPerformanceAssessment ea:LivePerformanceAssessment ) .

ea:AuthenticAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Measurement of accomplishments within a realistic, practical context relevant outside school. NOTE: one passage lists AuthenticAssessment as a coordinate sibling of PerformanceBasedAssessment, while another source states 'performance assessments may also be called authentic assessments' (synonymy). No disjointness is asserted between the two because the corpus explicitly states overlap." .

ea:ForwardLookingAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

ea:ContinuousAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasComponent ; owl:someValuesFrom ea:FormativeAssessment ] ) ] ;
  rdfs:comment "Evaluates a student's progress throughout a prescribed course; used as an alternative to the final-examination system; often includes formative assessment." .

ea:Examiner a owl:Class .
ea:ExpertExaminer a owl:Class ; rdfs:subClassOf ea:Examiner .
ea:hasExaminer a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Examiner .

ea:ComplexAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasRubric ; owl:someValuesFrom ea:Rubric ]
      [ a owl:Restriction ; owl:onProperty ea:hasExaminer ; owl:someValuesFrom ea:ExpertExaminer ] ) ] ;
  rdfs:comment "Requires a rubric and an expert examiner, e.g. thesis, funding proposal." .

ea:InterimAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Used to evaluate learning progress periodically and determine track to future summative assessments. Some educators consider interim assessments formative, others summative (disputed classification, noted but not resolved)." .

ea:ScreeningAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Determines whether students need specialized assistance/services or readiness to begin a course or program." .

ea:CommonAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Used across a school/district to ensure consistent evaluation; may be formative or summative." .

ea:Portfolio a owl:Class ; rdfs:label "Student Portfolio" .
ea:PhysicalPortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio .
ea:DigitalPortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio ; skos:altLabel "e-portfolio" .
[] a owl:AllDisjointClasses ; owl:members ( ea:PhysicalPortfolio ea:DigitalPortfolio ) .

ea:PortfolioBasedAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
      [ a owl:Restriction ; owl:onProperty ea:hasComponent ; owl:someValuesFrom ea:Assessment ] ) ] ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Compilations of academic work compiled by students and assessed by teachers to evaluate a body of knowledge over time." .

############################################
# 11. TEST SUBCLASSES
############################################

ea:WrittenTest a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "Administered on paper or computer." .
ea:PerformanceTest a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "Requires an examinee to actually perform a task/activity rather than answer about it, e.g. a behind-the-wheel driving test." .
ea:MultipleChoiceTest a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "A test composed primarily of multiple-choice items." .
ea:Quiz a owl:Class ; rdfs:subClassOf ea:Test, ea:FormativeAssessment ;
  rdfs:comment "A brief assessment covering a small amount of material, usually a formative, low-stakes assessment." .
ea:MidtermExam a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "Given near the middle of an academic term; a type of formative or summative assessment." .
ea:FinalExam a owl:Class ; rdfs:subClassOf ea:Test, ea:SummativeAssessment ;
  rdfs:comment "A final review and assessment of each student's knowledge, administered at the end of a course." .

ea:CompetitiveExamination a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test ea:NormReferencedAssessment ea:HighStakesAssessment ) ] ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and top rankers are selected." .

############################################
# 12. TEST ITEM HIERARCHY
############################################

ea:TestItem a owl:Class ; rdfs:label "Test Item" ;
  rdfs:comment "The general term for a unit of a test; colloquially called a 'question' though not all items are phrased as questions." .

ea:hasItem a owl:ObjectProperty ; rdfs:domain ea:Test ; rdfs:range ea:TestItem .
ea:isItemOf a owl:ObjectProperty ; owl:inverseOf ea:hasItem ; rdfs:domain ea:TestItem ; rdfs:range ea:Test .

ea:ItemStem a owl:Class ;
  rdfs:comment "The opening of an item - a problem, question, or incomplete statement to be completed." .
ea:hasStem a owl:ObjectProperty, owl:FunctionalProperty ; rdfs:domain ea:TestItem ; rdfs:range ea:ItemStem .

ea:AnswerOption a owl:Class .
ea:hasAnswerOption a owl:ObjectProperty ; rdfs:domain ea:TestItem ; rdfs:range ea:AnswerOption .
ea:hasKey a owl:ObjectProperty ; rdfs:subPropertyOf ea:hasAnswerOption ; rdfs:domain ea:TestItem ; rdfs:range ea:AnswerOption ;
  rdfs:comment "The correct answer option, called the key." .
ea:hasDistractor a owl:ObjectProperty ; rdfs:subPropertyOf ea:hasAnswerOption ; rdfs:domain ea:TestItem ; rdfs:range ea:AnswerOption ;
  rdfs:comment "An incorrect answer option, called a distractor." .

ea:ObjectiveItem a owl:Class ; rdfs:subClassOf ea:TestItem ;
  rdfs:comment "Objective question types include true/false, multiple-choice, multiple-response, and matching questions." .
ea:SubjectiveItem a owl:Class ; rdfs:subClassOf ea:TestItem ;
  rdfs:comment "Subjective questions include extended-response and essay questions." .
[] a owl:AllDisjointClasses ; owl:members ( ea:ObjectiveItem ea:SubjectiveItem ) .

ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .

ea:MultipleChoiceItem a owl:Class ;
  rdfs:subClassOf ea:ObjectiveItem ;
  skos:altLabel "MCQ" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
      [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ; owl:onClass ea:AnswerOption ] ) ] ;
  rdfs:comment "Only one answer may be keyed as correct, contrasted with multiple-response items." .

ea:MultipleResponseItem a owl:Class ;
  rdfs:subClassOf ea:ObjectiveItem ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
      [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:minQualifiedCardinality "2"^^xsd:nonNegativeInteger ; owl:onClass ea:AnswerOption ] ) ] ;
  rdfs:comment "More than one answer may be keyed as correct." .

[] a owl:AllDisjointClasses ; owl:members ( ea:TrueFalseItem ea:MultipleChoiceItem ea:MultipleResponseItem ea:MatchingItem ) .

ea:TrueFalseFamilyItem a owl:Class ; rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "One of the 'two families' of multiple-choice questions: requires choosing all appropriate answers. TENSION: this family is described as allowing multiple correct answers, which conflicts with the cardinality-1 definition of MultipleChoiceItem given elsewhere in the corpus (contrasted with MultipleResponseItem)." .
ea:OneBestAnswerFamilyItem a owl:Class ; rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "The second family: requires choosing only one answer from a list." .

ea:EssayItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem ;
  skos:altLabel "free response question", "FRQ", "extended-response item" ;
  rdfs:comment "An open-ended item requiring a prose response; also called a free response question." .
ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:TestItem ;
  rdfs:comment "Provides identifying characteristics and requires recall of the correct term; may or may not include a word bank." .

############################################
# 13. RUBRIC HIERARCHY
############################################

ea:Rubric a owl:Class ; skos:altLabel "scoring guide" ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses (Popham)." .

ea:HolisticRubric a owl:Class ; rdfs:subClassOf ea:Rubric ;
  rdfs:comment "Provides an overall rating for a piece of work, considering all aspects." .
ea:AnalyticRubric a owl:Class ; rdfs:subClassOf ea:Rubric ;
  rdfs:comment "Evaluates various dimensions or components separately." .
ea:DevelopmentalRubric a owl:Class ;
  rdfs:subClassOf ea:Rubric, ea:AnalyticRubric ;
  rdfs:comment "TENSION: 'Rubrics can be classified as holistic, analytic, or developmental' presents these as three coordinate (pairwise-disjoint) kinds, but the corpus also states 'Developmental rubrics, a subset of analytical rubrics'. Both the coordinate disjointness and the subordination to AnalyticRubric are asserted." .

[] a owl:AllDisjointClasses ; owl:members ( ea:HolisticRubric ea:AnalyticRubric ea:DevelopmentalRubric ) .

############################################
# 14. GRADING / SCORING APPROACHES
############################################

ea:GradingApproach a owl:Class .
ea:HolisticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach ;
  skos:altLabel "holistic scoring", "nonreductionist grading" ;
  rdfs:comment "Bases a grade on a paper's overall quality, treating the composition as a whole." .
ea:AnalyticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach ;
  rdfs:comment "Takes more factors into account, judging criterion by criterion." .
[] a owl:AllDisjointClasses ; owl:members ( ea:HolisticGrading ea:AnalyticGrading ) .

ea:TraitInformedScoring a owl:Class ; rdfs:subClassOf ea:GradingApproach ;
  rdfs:comment "Trains raters to score against a rubric with multiple criteria; comes close to analytic scoring but 'remains holistic at heart', a hybrid between HolisticGrading and AnalyticGrading." .

############################################
# 15. VALIDITY HIERARCHY
############################################

ea:Validity a owl:Class ;
  rdfs:comment "The degree to which a test measures what it is supposed to measure." .

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "logical validity" .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "criterion-related validity" .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity ea:FaceValidity ea:ConsequentialValidity ) .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:ConstructValidity rdfs:comment "TENSION: Content, criterion, construct, face and consequential validity are presented as coordinate (disjoint) categories of validity evidence in one passage. Another passage states construct validity 'subsumes all other types of validity' including content and criterion validity, which is modeled here as ContentValidity/CriterionValidity being subClassOf ConstructValidity, directly in tension with the disjointness above." .

ea:ConcurrentValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity ;
  rdfs:comment "Comparison between the measure and an outcome assessed at the same time." .
ea:PredictiveValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity ;
  rdfs:comment "Comparison between the measure and an outcome assessed at a later time." .
[] a owl:AllDisjointClasses ; owl:members ( ea:ConcurrentValidity ea:PredictiveValidity ) .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity ;
  rdfs:comment "Degree to which two measures of theoretically related constructs are in fact related." .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity ;
  rdfs:comment "Tests whether concepts that should be unrelated are, in fact, unrelated." .
[] a owl:AllDisjointClasses ; owl:members ( ea:ConvergentValidity ea:DiscriminantValidity ) .

ea:hasValidity a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Validity .

############################################
# 16. RELIABILITY HIERARCHY
############################################

ea:Reliability a owl:Class ;
  rdfs:comment "The consistency of an assessment; freedom of a measure from measurement error." .

ea:hasReliability a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Reliability .

# Axis A: general classes of reliability estimates (by estimation method)
ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Degree of agreement between two or more raters in their appraisals." .
ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "repeatability" ;
  rdfs:comment "Degree to which test scores are consistent from one test administration to the next for a single rater/instrument." .
ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "parallel-forms reliability", "alternate-forms reliability" ;
  rdfs:comment "Degree to which test scores are consistent when there is variation in methods/instruments used." .
ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Consistency of results across items within a test, commonly measured with Cronbach's alpha." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:InterRaterReliability ea:TestRetestReliability ea:InterMethodReliability ea:InternalConsistencyReliability ) .

ea:SplitHalfReliability a owl:Class ;
  rdfs:subClassOf ea:InterMethodReliability ;
  rdfs:comment "Treats the two halves of a measure as alternate forms." .

# Axis B: four types of reliability by source of error (distinct classification axis)
ea:StudentRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Includes personal problems, sickness, or fatigue of the student." .
ea:RaterRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Includes bias and subjectivity of the rater." .
ea:TestAdministrationRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Concerns the conditions of the test-taking process." .
ea:TestRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Related to the nature of the test itself." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:StudentRelatedReliability ea:RaterRelatedReliability ea:TestAdministrationRelatedReliability ea:TestRelatedReliability ) .

############################################
# 17. LEARNING OUTCOME
############################################

ea:LearningOutcome a owl:Class ;
  rdfs:comment "Statements about what students should be able to do by the end of a teaching session." .

ea:hasLearningOutcome a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:LearningOutcome .
ea:isLearningOutcomeOf a owl:ObjectProperty ; owl:inverseOf ea:hasLearningOutcome ;
  rdfs:domain ea:LearningOutcome ; rdfs:range ea:Assessment .

ea:IntendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ; skos:altLabel "aim" .
ea:MeasuredLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ; skos:altLabel "objective" .
ea:UnintendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome .

ea:LearningOutcome owl:disjointUnionOf
  ( ea:IntendedLearningOutcome ea:MeasuredLearningOutcome ea:UnintendedLearningOutcome ) .

ea:LearningOutcomeTaxonomy a owl:Class .
ea:BloomsTaxonomy a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:StructureOfObservedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy ; skos:altLabel "SOLO" .
ea:DIKWPyramid a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:ModelOfHierarchicalComplexity a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:BloomsTaxonomy ea:StructureOfObservedLearningOutcome ea:DIKWPyramid ea:ModelOfHierarchicalComplexity ) .

############################################
# 18. NORM GROUP
############################################

ea:NormGroup a owl:Class ;
  skos:altLabel "norming group" ;
  rdfs:comment "A comparison group used in the norming process from which a norm-referenced test's scores are derived." .

ea:hasNormGroup a owl:ObjectProperty ; rdfs:domain ea:NormReferencedAssessment ; rdfs:range ea:NormGroup .

############################################
# 19. PERIPHERAL CONCEPTS
############################################

ea:EducationalApproach a owl:Class .
ea:CompetencyBasedLearning a owl:Class ;
  rdfs:subClassOf ea:EducationalApproach ;
  skos:altLabel "proficiency-based learning", "mastery-based learning", "outcome-based learning", "performance-based education", "standards-based education" ;
  rdfs:comment "Systems of instruction, assessment, grading and reporting based on students demonstrating learned knowledge/skills." .

ea:TeacherEvaluationMethod a owl:Class .
ea:ValueAddedMeasure a owl:Class ; rdfs:subClassOf ea:TeacherEvaluationMethod ; skos:altLabel "growth measure" ;
  rdfs:comment "Statistical estimate of a teacher's effect on student learning during a school year." .
ea:StudentGrowthMeasure a owl:Class ; rdfs:subClassOf ea:TeacherEvaluationMethod ;
  rdfs:comment "A related but distinct method of using student test scores to quantify academic growth." .
ea:ValueAddedMeasure owl:disjointWith ea:StudentGrowthMeasure .

ea:ConstructiveAlignment a owl:Class ;
  rdfs:comment "Principle of devising learning activities and assessment tasks that directly address intended learning outcomes (Biggs)." .

ea:CorrectiveFeedback a owl:Class ;
  rdfs:comment "Feedback on a learner's understanding or performance that is nonevaluative, supportive, timely and specific." .

ea:TransferOfLearning a owl:Class ;
  rdfs:comment "Application of skill, knowledge or understanding to resolve a novel problem or situation." .
ea:NearTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning ;
  rdfs:comment "Application of skill to a novel problem in a similar context." .
ea:FarTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning ;
  rdfs:comment "Application of skill to a novel problem in a different context." .
[] a owl:AllDisjointClasses ; owl:members ( ea:NearTransfer ea:FarTransfer ) .

ea:PositiveTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning ;
  rdfs:comment "Learning supports novel problem solving." .
ea:NegativeTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning ;
  rdfs:comment "Prior learning inhibits performance on correlated tasks." .
[] a owl:AllDisjointClasses ; owl:members ( ea:PositiveTransfer ea:NegativeTransfer ) .

ea:LearningMode a owl:Class .
ea:FormalLearning a owl:Class ; rdfs:subClassOf ea:LearningMode .
ea:NonFormalLearning a owl:Class ; rdfs:subClassOf ea:LearningMode ;
  rdfs:comment "Organized learning outside the formal learning system, e.g. clubs and workshops." .
ea:InformalLearning a owl:Class ; rdfs:subClassOf ea:LearningMode ;
  rdfs:comment "Less structured than non-formal learning; occurs through day-to-day experience." .
ea:LearningMode owl:disjointUnionOf ( ea:FormalLearning ea:NonFormalLearning ea:InformalLearning ) .

ea:AssessmentQualityIssue a owl:Class .
ea:ScoreInflation a owl:Class ; rdfs:subClassOf ea:AssessmentQualityIssue ;
  rdfs:comment "Scores increase without genuine improvement in learning." .
ea:MeasurementError a owl:Class ; rdfs:subClassOf ea:AssessmentQualityIssue ;
  rdfs:comment "Difference between what a test score indicates and a student's actual knowledge/ability, or errors in data collection/reporting." .

ea:Proficiency a owl:Class ;
  rdfs:comment "Determination, based on standards or a measurement system, of whether a student/teacher meets a defined performance level." .

############################################
# 20. DATATYPE PROPERTIES
############################################

ea:hasReliabilityCoefficient a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Reliability ;
  rdfs:range xsd:decimal ;
  rdfs:comment "Ranges from 0.00 (much error) to 1.00 (no error)." .

ea:hasItemCount a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range xsd:integer .

ea:hasCutScore a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionReferencedTest ;
  rdfs:range xsd:decimal ;
  rdfs:comment "The minimum score needed to pass a mastery (criterion-referenced) test." .

ea:hasRubric a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Rubric .
ea:isRubricOf a owl:ObjectProperty ; owl:inverseOf ea:hasRubric ; rdfs:domain ea:Rubric ; rdfs:range ea:Assessment .
